// Generate the stable named components from bundled plugins' manifests (TODO 138.8).
import fs from "node:fs";
import ts from "typescript";
import { COMPONENT_MANIFESTS } from "../src/lib/plugins/manifests.js";

const header =
  "Generated by scripts/generate-python-signatures.mjs from src/lib/plugins/*.manifest.js; do not edit.";
const doc = (text) => `/** ${text.replaceAll("*/", "*\\/")} */`;

export function pluginComponentEntries(core) {
  const entries = {};
  for (const { kind, signature, types, required = [] } of COMPONENT_MANIFESTS) {
    if (core.components[kind] || entries[kind])
      throw Error(
        `${kind}: its component metadata must live only in its plugin manifest.`,
      );
    for (const name of Object.keys(signature.options))
      if (!types[name])
        throw Error(
          `${kind}.${name}: the plugin component manifest needs its TypeScript type.`,
        );
    for (const name of [...Object.keys(types), ...required])
      if (!signature.options[name])
        throw Error(
          `${kind}.${name}: the plugin component manifest needs its documented option.`,
        );
    entries[kind] = signature;
  }
  return entries;
}

export function pluginComponentTypes(root) {
  const source = ts.createSourceFile(
    "publicTypes.ts",
    fs.readFileSync(`${root}/src/lib/plot/publicTypes.ts`, "utf8"),
    ts.ScriptTarget.Latest,
    true,
  );
  // The existing internal row-value alias remains defined once; generated props copy its declaration.
  const rowNumbers = source.statements
    .find((node) => node.name?.text === "RowNumbers")
    .getText(source);
  const interfaces = COMPONENT_MANIFESTS.map(
    ({ kind, signature, types, required = [], internal = {} }) => {
      const members = Object.entries(types).map(
        ([name, type]) =>
          `  ${doc(signature.options[name].doc)}\n  ${name}${required.includes(name) ? "" : "?"}: ${type};`,
      );
      for (const [name, entry] of Object.entries(internal))
        members.push(`  ${doc(entry.doc)}\n  ${name}?: ${entry.type};`);
      return `${doc(signature.summary)}\nexport interface ${kind}Props {\n  children?: Snippet;\n${members.join("\n")}\n}`;
    },
  );
  return `// ${header}\nimport type { Snippet } from "svelte";\nimport type { ColumnName, Expression } from "../../plot/publicTypes.js";\n${rowNumbers}\n\n${interfaces.join("\n\n")}\n`;
}

export function pluginComponentWrapper({ kind, bindings = {}, inspect }) {
  const bound = Object.entries(bindings);
  const bindProps = bound
    .map(
      ([name, value]) =>
        `${name} = $bindable(${value === null ? "" : JSON.stringify(value)}), `,
    )
    .join("");
  const configure = bound.length
    ? `\n  function configure(patch) {\n${bound.map(([name]) => `    if (Object.hasOwn(patch, "${name}")) ${name} = patch.${name};`).join("\n")}\n  }`
    : "";
  const inspection = inspect
    ? `\n  ${doc(inspect.doc)}\n  export async function ${inspect.method}(): Promise<${inspect.type} | null> {\n    await handle.whenSettled();\n    return (await handle.inspect()) ?? null;\n  }`
    : "";
  return `<!-- ${header} -->\n<script lang="ts">\n  import Transform from "./transform.svelte";\n  import type { ${kind}Props${inspect ? `, ${inspect.type}` : ""} } from "./publicTypes.js";\n  let { children, ${bindProps}...props }: ${kind}Props = $props();\n  let handle = $state<any>();${configure}\n  export const subscribe = (listener) => handle.subscribe(listener);\n  export const update = (patch) => handle.update(patch);\n  export const whenSettled = () => handle.whenSettled();\n  /** Its output as a data source (TODO 142.3): <Data value={handle}>. */\n  export const dataSource = () => handle?.dataSource?.();${inspection}\n</script>\n<Transform bind:this={handle} kind="${kind}" {...props}${bound.map(([name]) => ` {${name}}`).join("")}${bound.length ? " onconfigure={configure}" : ""}>{@render children?.()}</Transform>\n`;
}

export function pluginComponentOutputs(root) {
  return [
    ["src/lib/plugins/generated/types.ts", pluginComponentTypes(root)],
    [
      "src/lib/scene/options.plugins.json",
      JSON.stringify(
        Object.fromEntries(
          COMPONENT_MANIFESTS.map(({ kind, signature }) => [kind, signature]),
        ),
        null,
        2,
      ) + "\n",
    ],
    ...COMPONENT_MANIFESTS.map((manifest) => [
      `src/lib/plot/${manifest.kind[0].toLowerCase() + manifest.kind.slice(1)}.svelte`,
      pluginComponentWrapper(manifest),
    ]),
  ];
}

/** Numerical schemas are read from the actual plugin declarations, never copied into wrappers. */
export async function pluginParameterSchemas() {
  const [
    { FIRST_PARTY_PLUGINS },
    { createPluginRegistry },
    { pluginLibraries },
  ] = await Promise.all([
    import("../src/lib/plugins/index.js"),
    import("../src/lib/plot/plugins/registry.js"),
    import("../src/lib/plot/plugins/runtime.js"),
  ]);
  const registry = createPluginRegistry(pluginLibraries);
  for (const plugin of FIRST_PARTY_PLUGINS) registry.register(plugin);
  return Object.fromEntries(
    registry
      .kinds("transform")
      .map((kind) => [kind, registry.get("transform", kind).parameters ?? {}]),
  );
}
